  `arrival_airport` varchar(50) NOT NULL COMMENT '到达机场',
  `checkin_start_time` time NOT NULL COMMENT '值机开始时间',
  `checkin_end_time` time NOT NULL COMMENT '值机结束时间',
  `price` decimal(10,2) NOT NULL COMMENT '价格（元，保留两位小数）',
  `airline_company` varchar(50) NOT NULL COMMENT '航空公司',
  `status` varchar(20) NOT NULL COMMENT '状态',
  `left_tickets` int(11) NOT NULL COMMENT '剩余票数',
  PRIMARY KEY (`flight_id`),
  UNIQUE KEY `uk_flight_number_date` (`flight_number`,`date`)
